                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Categories data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching categories:', error);
            throw error;
        }
    }

    // Upload a new reel
    static async uploadReel(formData) {
        try {
            const response = await fetch(`${API_BASE_URL}/upload`, {
                method: 'POST',
                body: formData
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Upload response:', data);
            return data;
        } catch (error) {
            console.error('Error uploading reel:', error);
            throw error;
        }
    }

    // Get reels for the authenticated influencer
    static async getInfluencerReels() {
        try {
            const response = await fetch(`${API_BASE_URL}/my-reels`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Reels data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching reels:', error);
            throw error;
        }
    }

    // Placeholder method for fetching related products
